/**
 * `npm run local` — runs the whole Open Media stack on this computer:
 * local Supabase (database, auth, test inbox), the mail/public-API Worker
 * (via wrangler dev), and the web app. Ctrl+C stops the Worker and web app;
 * `npm run local:stop` also stops the database.
 *
 * Generated files stay inside the repository and are gitignored:
 * .local/, .env.development.local, services/mail-sync/.dev.vars.
 */
import { ChildProcess, execFileSync, spawn } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { homedir, platform } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const mailService = join(root, 'services', 'mail-sync');
const localDir = join(root, '.local');
const appURL = 'http://localhost:8081';
const apiURL = 'http://127.0.0.1:8787';
const inboxURL = 'http://127.0.0.1:54324';

const nodeBin = findNode22();
const childEnv = { ...process.env, PATH: `${dirname(nodeBin)}:${process.env.PATH ?? ''}`, FORCE_COLOR: '1' };
const children: ChildProcess[] = [];

main().catch((error) => {
  console.error(`\n✗ ${error instanceof Error ? error.message : error}`);
  stopChildren();
  process.exit(1);
});

async function main() {
  step('Checking Docker');
  await ensureDocker();

  const smtpEnv = join(root, 'supabase', '.env');
  if (!existsSync(smtpEnv)) {
    writeFileSync(smtpEnv, '# Sign-in email delivery for local Supabase. Configure with `npm run local:email`.\nOPEN_MEDIA_SMTP_ENABLED=false\nOPEN_MEDIA_SMTP_HOST=localhost\nOPEN_MEDIA_SMTP_PORT=587\nOPEN_MEDIA_SMTP_USER=\nOPEN_MEDIA_SMTP_PASS=\nOPEN_MEDIA_SMTP_FROM=no-reply@localhost\n', { mode: 0o600 });
  }

  step('Starting local Supabase (database, auth, test inbox)');
  run('npx', ['supabase', 'start'], { quiet: true });
  run('npx', ['supabase', 'migration', 'up', '--local'], { quiet: true });
  const status = JSON.parse(run('npx', ['supabase', 'status', '-o', 'json'], { quiet: true })) as Record<string, string>;
  const supabaseURL = status.API_URL;
  const publishableKey = status.PUBLISHABLE_KEY;
  if (!supabaseURL || !publishableKey) throw new Error('Could not read the local Supabase URL and key from `supabase status`.');

  step('Writing local configuration');
  mkdirSync(localDir, { recursive: true });
  writeFileSync(join(localDir, 'README.md'), '# .local\n\nMachine-local state for `npm run local` (gitignored). `mail-credentials-key` encrypts saved mailbox passwords in the local database; deleting it makes saved mailboxes unreadable, so reconnect them afterwards.\n');
  const keyFile = join(localDir, 'mail-credentials-key');
  if (!existsSync(keyFile)) writeFileSync(keyFile, randomBytes(32).toString('base64'), { mode: 0o600 });
  const mailKey = readFileSync(keyFile, 'utf8').trim();

  writeFileSync(join(mailService, '.dev.vars'), [
    '# Generated by `npm run local`. Local development only.',
    `SUPABASE_URL=${supabaseURL}`,
    `SUPABASE_PUBLISHABLE_KEY=${publishableKey}`,
    `MAIL_CREDENTIALS_KEY=${mailKey}`,
    `CONVO_APP_ORIGIN=${appURL}`,
    `EVENTS_PUBLIC_ORIGIN=${apiURL}`,
    'MAIL_ALLOW_LOCAL_SERVERS=true',
    '',
  ].join('\n'), { mode: 0o600 });

  writeFileSync(join(root, '.env.development.local'), [
    '# Generated by `npm run local`: points development builds at the local stack.',
    '# Delete this file to use the production backend in `npm run web`.',
    `EXPO_PUBLIC_SUPABASE_URL=${supabaseURL}`,
    `EXPO_PUBLIC_SUPABASE_PUBLISHABLE_KEY=${publishableKey}`,
    `EXPO_PUBLIC_OPEN_MEDIA_API_URL=${apiURL}`,
    `EXPO_PUBLIC_OPEN_MEDIA_PUBLIC_API_URL=${apiURL}`,
    '',
  ].join('\n'));

  step('Starting the mail and public API service');
  start('api', 'npx', ['wrangler', 'dev', '--port', '8787', '--ip', '127.0.0.1'], mailService);
  await waitFor(`${apiURL}/health`, 'mail service');

  step('Starting the web app');
  start('web', 'npx', ['expo', 'start', '--web', '--port', '8081'], root);
  await waitFor(appURL, 'web app', 180);

  const smtp = readSmtpEnv();
  console.log(`
✓ Open Media is running

  App              ${appURL}
  Mail + API       ${apiURL}   (public API: ${apiURL}/v1/posts)
  Sign-in emails   ${smtp.enabled ? `sent to your real inbox via ${smtp.host}` : `local test inbox → ${inboxURL}  (run \`npm run local:email\` to use your own email provider)`}
  Test SMTP        localhost:54325 (no TLS; works only for this local setup)

  Ctrl+C stops the app and mail service. \`npm run local:stop\` also stops the database.
`);
  if (platform() === 'darwin' && !process.env.OPEN_MEDIA_NO_BROWSER) spawn('open', [appURL], { stdio: 'ignore', detached: true }).unref();
}

function findNode22(): string {
  const [major, minor] = process.versions.node.split('.').map(Number);
  if (major > 22 || (major === 22 && minor >= 13)) return process.execPath;
  const nvmVersions = join(process.env.NVM_DIR ?? join(homedir(), '.nvm'), 'versions', 'node');
  if (existsSync(nvmVersions)) {
    const candidates = readdirSync(nvmVersions)
      .map((name) => ({ name, parts: name.replace(/^v/, '').split('.').map(Number) }))
      .filter(({ parts: [a, b] }) => a > 22 || (a === 22 && b >= 13))
      .sort((x, y) => y.parts[0] - x.parts[0] || y.parts[1] - x.parts[1] || y.parts[2] - x.parts[2]);
    if (candidates[0]) return join(nvmVersions, candidates[0].name, 'bin', 'node');
  }
  throw new Error(`Node.js 22.13 or newer is required (found ${process.versions.node}). Run \`nvm install 22 && nvm use 22\`, then try again.`);
}

async function ensureDocker() {
  if (dockerReady()) return;
  if (platform() !== 'darwin') throw new Error('Docker is not running. Start Docker, then run `npm run local` again.');
  console.log('  Opening Docker Desktop…');
  spawn('open', ['-a', 'Docker'], { stdio: 'ignore' });
  for (let attempt = 0; attempt < 60; attempt += 1) {
    await sleep(3000);
    if (dockerReady()) return;
  }
  throw new Error('Docker did not start within 3 minutes. Open Docker Desktop, wait until it is running, then try again.');
}

function dockerReady(): boolean {
  try { execFileSync('docker', ['info'], { stdio: 'ignore' }); return true; } catch { return false; }
}

function run(command: string, args: string[], options: { quiet?: boolean } = {}): string {
  try {
    return execFileSync(command, args, { cwd: root, env: childEnv, encoding: 'utf8', stdio: options.quiet ? ['ignore', 'pipe', 'pipe'] : 'inherit' }) ?? '';
  } catch (error) {
    const output = error as { stderr?: string; stdout?: string };
    throw new Error(`\`${command} ${args.join(' ')}\` failed.\n${output.stderr || output.stdout || ''}`);
  }
}

function start(label: string, command: string, args: string[], cwd: string, extraEnv: Record<string, string> = {}) {
  const child = spawn(command, args, { cwd, env: { ...childEnv, ...extraEnv }, stdio: ['ignore', 'pipe', 'pipe'] });
  const prefix = `[${label}] `;
  const relay = (chunk: Buffer) => process.stdout.write(chunk.toString().split('\n').filter(Boolean).map((line) => prefix + line).join('\n') + '\n');
  child.stdout?.on('data', relay);
  child.stderr?.on('data', relay);
  child.on('exit', (code) => {
    if (!shuttingDown) {
      console.error(`\n✗ ${label} stopped (exit ${code}). Stopping Open Media.`);
      stopChildren();
      process.exit(code ?? 1);
    }
  });
  children.push(child);
}

let shuttingDown = false;
function stopChildren() {
  shuttingDown = true;
  for (const child of children) if (!child.killed) child.kill('SIGINT');
}
process.on('SIGINT', () => { console.log('\nStopping Open Media (Supabase keeps running; `npm run local:stop` stops it)…'); stopChildren(); setTimeout(() => process.exit(0), 1500); });
process.on('SIGTERM', () => { stopChildren(); process.exit(0); });

async function waitFor(url: string, label: string, seconds = 90) {
  for (let elapsed = 0; elapsed < seconds; elapsed += 2) {
    try { if ((await fetch(url)).status < 500) return; } catch { /* not ready yet */ }
    await sleep(2000);
  }
  throw new Error(`The ${label} did not start within ${seconds} seconds. See the log above.`);
}

function readSmtpEnv(): { enabled: boolean; host: string } {
  const file = join(root, 'supabase', '.env');
  if (!existsSync(file)) return { enabled: false, host: '' };
  const values = Object.fromEntries(readFileSync(file, 'utf8').split('\n').map((line) => line.split('=')).filter((parts) => parts.length >= 2).map(([key, ...rest]) => [key.trim(), rest.join('=').trim()]));
  return { enabled: values.OPEN_MEDIA_SMTP_ENABLED === 'true', host: values.OPEN_MEDIA_SMTP_HOST ?? '' };
}

function step(message: string) { console.log(`→ ${message}`); }
function sleep(ms: number) { return new Promise((done) => setTimeout(done, ms)); }
